document.addEventListener('DOMContentLoaded', function () {
    const menuToggle = document.getElementById('menu-toggle');
    const header = document.getElementById('header');

    if (menuToggle && header) {
      menuToggle.addEventListener('click', function (e) {
        e.preventDefault();
        header.classList.toggle('show-menu');
        const expanded = menuToggle.getAttribute('aria-expanded') === 'true' || false;
        menuToggle.setAttribute('aria-expanded', !expanded);
      });

      // Mobile dropdown toggle: click expands/collapses submenu instead of navigating
      document.querySelectorAll('.dropdown-toggle').forEach(function (toggle) {
        toggle.addEventListener('click', function (e) {
          if (window.innerWidth <= 991) {
            e.preventDefault();
            toggle.closest('.has-dropdown').classList.toggle('open');
          }
        });
      });

      // Close menu when clicking on menu items (for mobile), skip dropdown toggles
      document.querySelectorAll('.menu a:not(.dropdown-toggle)').forEach(function (item) {
        item.addEventListener('click', function () {
          header.classList.remove('show-menu');
          menuToggle.setAttribute('aria-expanded', 'false');
          document.querySelectorAll('.has-dropdown').forEach(function (d) { d.classList.remove('open'); });
        });
      });

      // Close menu when clicking outside
      document.addEventListener('click', function (e) {
        if (!header.contains(e.target) && header.classList.contains('show-menu')) {
          header.classList.remove('show-menu');
          menuToggle.setAttribute('aria-expanded', 'false');
          document.querySelectorAll('.has-dropdown').forEach(function (d) { d.classList.remove('open'); });
        }
      });
    }
  });